    "After each compose, T-DJ compares the night with sets from working DJs and fixes what it can",
  "settings.after_every_compose_the_night_is":
    "After every compose the night is checked against the published DJ sets and the engine's own rules (your heatmap's best years, one recording period per tanda, the golden core, bridge cues) and improved where a change makes nothing worse. The change summary under the set says what changed. Off: the night is shown as composed; the Benchmark sheet can still improve it.",
